==> summaries/generation/context/templates/file/open_flags.md <==
Map `open` flags onto the API. `__file_open` never creates a file, and its mode string only sets `__file_flags`: "w" does not truncate and "a" does not append. Create, truncate and set the mode explicitly.

```c
#define O_ACCMODE 0003
#define O_WRONLY  01
#define O_RDWR    02
#define O_CREAT   0100
#define O_EXCL    0200
#define O_TRUNC   01000
#define O_APPEND  02000

int foo(const char *pathname, int flags, mode_t mode){
    int exists = __file_exists(pathname);

    if (exists && (flags & O_CREAT) && (flags & O_EXCL))
        return -1;                          // EEXIST
    if (!exists && !(flags & O_CREAT))
        return -1;                          // ENOENT

    // The access mode, and O_APPEND, as an fopen mode string
    const char *how;
    if ((flags & O_ACCMODE) == O_RDWR)
        how = (flags & O_APPEND) ? "a+" : "r+";
    else if ((flags & O_ACCMODE) == O_WRONLY)
        how = (flags & O_APPEND) ? "a" : "w";
    else
        how = "r";

    if (!exists)
        __file_create(pathname);

    int fd = __file_open(pathname, how);

    if (!exists)
        __file_set_mode(fd, mode & ~022);   // the umask applies on creation
    if (flags & O_TRUNC)
        __file_set_size(fd, 0);

    return fd;
}
```

==> summaries/generation/context/templates/file/permissions.md <==
Check a file's permission bits before opening it (EACCES). `__file_open` itself ignores them, so read them through a descriptor first. The owner's bits: 0400 read, 0200 write.

```c
int foo(const char *pathname, int flags){
    mode_t mode;

    int probe = __file_open(pathname, "r");
    __file_mode(probe, &mode);
    __file_close(probe);

    int reads  = (flags & O_ACCMODE) != O_WRONLY;
    int writes = (flags & O_ACCMODE) != O_RDONLY;

    if ((reads && !(mode & 0400)) || (writes && !(mode & 0200)))
        return -1;
    ...
}
```

==> summaries/generation/context/templates/file/seek.md <==
Compute a seek position: from 0, the current offset or the size, plus the offset. A negative result, or an unknown `whence`, fails (EINVAL). `__file_set_offset` needs it concrete: fork or unfold first.

```c
#define SEEK_SET 0
#define SEEK_CUR 1
#define SEEK_END 2

off_t foo(int fd, off_t offset, int whence){
    off_t base;

    if (whence == SEEK_SET)
        base = 0;
    else if (whence == SEEK_CUR)
        base = __file_offset(fd);
    else if (whence == SEEK_END)
        base = __file_size(fd);     // may be symbolic: unfold it
    else
        return -1;

    off_t pos = base + offset;
    if (pos < 0)
        return -1;

    return __file_set_offset(fd, pos);
}
```
